// Captures what the Admin contact-change and password-reset write routes put on the wire and leave in the database, by
// running the real Admin Route Handlers (apps/admin/src/app/api/contact-change-requests/**, password-reset-requests/**) and
// the real @rotra/db services (Prisma) against a throwaway local Postgres. The harness is capture-writes-base.mjs; the Go
// side is apps/api/internal/writetest. Groups:
//   resetreview     POST /api/password-reset-requests/{requestId}                       (issue a link, decline)
//   contactcreate   POST /api/contact-change-requests                                   (the owner enters a request)
//   contactdecide   POST /api/contact-change-requests/{requestId}/{approve|decline|check|retry}
//
//   docker run -d --rm --name rotra-capture-pg -e POSTGRES_PASSWORD=test -p 127.0.0.1:55461:5432 postgres:16-alpine
//   source ~/.nvm/nvm.sh && nvm use
//   ROTRA_CAPTURE_DB_URL=postgres://postgres:test@127.0.0.1:55461/postgres \
//     node node_modules/.pnpm/vitest@*/node_modules/vitest/vitest.mjs run --config apps/api/testdata/tools/vitest.capture.config.mjs apps/api/testdata/tools/capture-writes-contacts.test.mjs [-t contactdecide]
//
// Refuses any host but 127.0.0.1/localhost. It creates its own database (rotra_capture_<n>) and drops it. The cases and the
// seed (contacts.seed.sql: players.seed.sql plus password-reset requests) are generated by
// gen-writes-admin-contact-cases.py. Output: apps/api/internal/adminwrites/testdata/<group>.golden.json.
//
// What is replaced, and only this:
//   verifySubject      answers the step's subject (a step with none is signed out), so loadAccountContext and every service run
//                      for real. AUTH_PROVIDER is 'rotra' here: the seed's player accounts are signed in by the platform, which
//                      is what eligible() (password-resets.ts) tests for, and what Go has.
//   generatePlayerRecoveryToken  answers a made-up token (the real one asks Supabase for a link). The route puts it in the
//                      answer; the cases redact `token`, and the stored digest is pinned as "has a link", not as a value.
//   supabaseProviderAdmin().readLogin/updateLogin  the sign-in provider of a contact change. There is no Supabase here and Go
//                      has none: the login of a player is its identity (auth_identities). This mock does what Go does: the
//                      email of a login is the identity's login key (changed by updateLogin; a key another login has is refused
//                      as provider_rejected; a player with no identity is provider_unavailable on update and null on read). A
//                      phone is not part of an identity, so the mock keeps it in memory per case: an update stores it, and a
//                      read answers it, else the contact's own phone. Go keeps no phone: it treats a phone update as done (the
//                      cases never read back a phone that was not updated first; the Go-only tests pin that difference).
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { afterAll, beforeAll, test, vi } from 'vitest'
import { captureWrites, openCaptureDb, root } from './capture-writes-base.mjs'

vi.mock('../../../../packages/db/src/auth/supabase.ts', async (importOriginal) => ({
  ...(await importOriginal()),
  AUTH_PROVIDER: 'rotra',
  verifySubject: async () => {
    const { currentSubject } = await import('./capture-writes-base.mjs')
    const subject = currentSubject()
    return subject ? { provider: 'supabase', subject } : null
  },
}))

vi.mock('../../../../packages/db/src/auth/supabase-provider-admin.ts', async (importOriginal) => {
  const { ProviderError } = await import('../../../../packages/db/src/auth/provider-admin.ts')
  const phones = new Map()
  globalThis.__resetPhones = () => phones.clear()
  const identity = async (subject) => {
    const { rows } = await globalThis.__captureDb.query(
      `SELECT login_key FROM auth_identities WHERE id = $1 AND audience = 'player'`,
      [subject],
    )
    return rows[0] ?? null
  }
  return {
    ...(await importOriginal()),
    generatePlayerRecoveryToken: async (subject) => `recovery-token-${subject}`,
    supabaseProviderAdmin: () => ({
      async readLogin(subject) {
        const found = await identity(subject)
        if (!found) return null
        const { rows } = await globalThis.__captureDb.query(
          'SELECT c.phone_e164 FROM player_accounts a JOIN player_private_contacts c ON c.player_id = a.player_id WHERE a.auth_subject = $1',
          [subject],
        )
        return { email: found.login_key, phoneE164: phones.get(subject) ?? rows[0]?.phone_e164 ?? null }
      },
      async updateLogin({ subject, email, phoneE164 }) {
        if (!(await identity(subject))) throw new ProviderError('provider_unavailable')
        if (email) {
          try {
            await globalThis.__captureDb.query('UPDATE auth_identities SET login_key = $1 WHERE id = $2', [email, subject])
          } catch (error) {
            if (error?.code === '23505') throw new ProviderError('provider_rejected')
            throw error
          }
        }
        if (phoneE164) phones.set(subject, phoneE164)
      },
    }),
  }
})

const here = dirname(fileURLToPath(import.meta.url))
const testdata = resolve(here, '../../internal/adminwrites/testdata')
const apiDir = resolve(root, 'apps/admin/src/app/api')

let capture
beforeAll(async () => {
  capture = await openCaptureDb()
  globalThis.__captureDb = capture.db
})
afterAll(async () => {
  await capture?.close()
})

for (const name of ['resetreview', 'contactcreate', 'contactdecide']) {
  test(name, async () => {
    await captureWrites({ db: capture.db, testdata, name, apiDir, beforeCase: () => globalThis.__resetPhones?.() })
  })
}
